_BORRAR_MENCIONES = "\nCREATE FUNCTION borrar_menciones(p_texto text, p_palabras text[], p_literales text[])\nRETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, public AS $$\nDECLARE\n    v text := p_texto;\n    m text;\nBEGIN\n    IF v IS NULL THEN\n        RETURN NULL;\n    END IF;\n    -- Cada caracter que no es letra ni digito va escapado: la mencion se busca literal.\n    FOREACH m IN ARRAY coalesce(p_palabras, '{}') LOOP\n        v := regexp_replace(\n            v, '\\m' || regexp_replace(m, '([^[:alnum:][:space:]])', '\\\\\\1', 'g') || '\\M',\n            '[anonimizado]', 'gi');\n    END LOOP;\n    FOREACH m IN ARRAY coalesce(p_literales, '{}') LOOP\n        v := regexp_replace(\n            v, regexp_replace(m, '([^[:alnum:]])', '\\\\\\1', 'g'), '[anonimizado]', 'gi');\n    END LOOP;\n    RETURN v;\nEND\n$$\n"

_BORRAR_MENCIONES_JSON = "\nCREATE FUNCTION borrar_menciones_json(p_valor jsonb, p_palabras text[], p_literales text[])\nRETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, public AS $$\nBEGIN\n    RETURN CASE jsonb_typeof(p_valor)\n        WHEN 'string' THEN to_jsonb(borrar_menciones(p_valor #>> '{}', p_palabras, p_literales))\n        WHEN 'array' THEN coalesce(\n            (SELECT jsonb_agg(borrar_menciones_json(x, p_palabras, p_literales) ORDER BY o)\n             FROM jsonb_array_elements(p_valor) WITH ORDINALITY AS t(x, o)),\n            '[]'::jsonb)\n        WHEN 'object' THEN coalesce(\n            (SELECT jsonb_object_agg(k, borrar_menciones_json(v, p_palabras, p_literales))\n             FROM jsonb_each(p_valor) AS t(k, v)),\n            '{}'::jsonb)\n        ELSE p_valor\n    END;\nEND\n$$\n"

_ANONIMIZAR_ANTERIOR = "\nCREATE OR REPLACE FUNCTION anonimizar_familia(p_familia uuid) RETURNS SETOF text\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$\nDECLARE\n    f familias%ROWTYPE;\n    v_ids text[];\n    v_anonimo constant text := '[anonimizado]';\n    -- Prefijo internacional 999: no esta asignado a ningun pais.\n    v_telefono constant text := '+99900000000';\n    v_quitar constant text[] :=\n        ARRAY['ip', 'user_agent', 'nombre', 'documento', 'email', 'telefono'];\n    v_personales constant text[] := ARRAY[\n        'titular_nombre', 'documento', 'email', 'telefono', 'barrio', 'direccion', 'relacion',\n        'descripcion',\n        'complemento', 'latitud', 'longitud',\n        'notas', 'motivo_baja', 'nombre', 'destino', 'contenido', 'asunto', 'variables',\n        'email_titular', 'ultimos4', 'comentario', 'aceptacion', 'evidencia_aceptacion', 'datos',\n        'contacto_nombre', 'contacto_telefono', 'contacto_email'\n    ];\nBEGIN\n    IF current_setting('app.rol', true) IS DISTINCT FROM 'admin' THEN\n        RAISE EXCEPTION 'Solo un administrador anonimiza una familia'\n            USING ERRCODE = 'insufficient_privilege';\n    END IF;\n    SELECT * INTO f FROM familias WHERE id = p_familia FOR UPDATE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Familia % no encontrada', p_familia USING ERRCODE = 'no_data_found';\n    END IF;\n    IF f.anonimizada_en IS NOT NULL THEN\n        RAISE EXCEPTION 'La familia ya esta anonimizada' USING ERRCODE = 'check_violation';\n    END IF;\n    IF EXISTS (\n        SELECT 1 FROM contratos\n        WHERE familia_id = p_familia AND estado IN ('activa', 'en_mora', 'congelada')\n    ) THEN\n        RAISE EXCEPTION 'La familia tiene un contrato vigente' USING ERRCODE = 'check_violation';\n    END IF;\n\n    -- Ficheros con datos personales: fotos de las mascotas, PDF de contratos y carnets y\n    -- los documentos que subio el equipo, salvo los examenes externos, que son clinicos.\n    RETURN QUERY\n        WITH purgados AS (\n            UPDATE archivos a SET purgado_en = now(), nombre_original = 'anonimizado'\n            WHERE a.purgado_en IS NULL AND a.id IN (\n                SELECT foto_archivo_id FROM mascotas WHERE familia_id = p_familia\n                UNION SELECT documento_archivo_id FROM contratos WHERE familia_id = p_familia\n                UNION SELECT c.archivo_id FROM carnets_emitidos c\n                      JOIN mascotas m ON m.id = c.mascota_id WHERE m.familia_id = p_familia\n                UNION SELECT archivo_id FROM documentos_familia\n                      WHERE familia_id = p_familia AND categoria <> 'examen_externo'\n            )\n            RETURNING a.clave\n        )\n        SELECT clave::text FROM purgados;\n\n    UPDATE mascotas SET nombre = 'Mascota', foto_archivo_id = NULL WHERE familia_id = p_familia;\n    UPDATE peludos_solicitud SET nombre = 'Mascota' WHERE familia_id = p_familia;\n    IF f.usuario_portal_id IS NOT NULL THEN\n        UPDATE usuarios\n        SET nombre = 'Anonimizado', email = 'anonimizado-' || id || '@invalid.local',\n            telefono = NULL, activo = false\n        WHERE id = f.usuario_portal_id;\n        UPDATE sesiones SET revocada_en = coalesce(revocada_en, now())\n        WHERE usuario_id = f.usuario_portal_id;\n        UPDATE tokens_uso_unico SET expira_en = least(expira_en, now())\n        WHERE usuario_id = f.usuario_portal_id;\n    END IF;\n    DELETE FROM conversaciones_comerciales\n    WHERE telefono = f.telefono\n       OR interesado_id IN (SELECT id FROM interesados WHERE familia_id = p_familia);\n    DELETE FROM conversaciones_whatsapp WHERE familia_id = p_familia OR telefono = f.telefono;\n    UPDATE interesados SET nombre = NULL, telefono = NULL, email = NULL, datos = '{}'\n    WHERE familia_id = p_familia;\n    UPDATE mensajes SET destino = NULL, contenido = NULL, asunto = NULL, variables = '[]'\n    WHERE familia_id = p_familia;\n    UPDATE solicitudes_afiliacion SET aceptacion = aceptacion - v_quitar,\n        contacto_nombre = CASE WHEN contacto_nombre IS NULL THEN NULL ELSE 'Anonimizado' END,\n        contacto_telefono = CASE WHEN contacto_telefono IS NULL THEN NULL ELSE v_telefono END,\n        contacto_email = NULL\n    WHERE familia_id = p_familia;\n    UPDATE contratos SET evidencia_aceptacion = evidencia_aceptacion - v_quitar\n    WHERE familia_id = p_familia;\n    UPDATE medios_pago_recurrente\n    SET email_titular = 'anonimizado@invalid.local', ultimos4 = NULL, activo = false\n    WHERE familia_id = p_familia;\n    UPDATE encuestas SET comentario = NULL WHERE familia_id = p_familia;\n    UPDATE destinatarios_campana SET telefono = v_telefono WHERE familia_id = p_familia;\n    UPDATE documentos_familia SET descripcion = NULL WHERE familia_id = p_familia;\n    -- Tambien los que se conservan: el nombre original puede llevar datos personales.\n    UPDATE archivos SET nombre_original = 'anonimizado'\n    WHERE id IN (SELECT archivo_id FROM documentos_familia WHERE familia_id = p_familia);\n    UPDATE contactos_familia\n    SET nombre = 'Anonimizado', telefono = v_telefono, email = NULL, relacion = NULL\n    WHERE familia_id = p_familia;\n    UPDATE familias\n    SET titular_nombre = 'Anonimizado',\n        documento = 'ANON' || upper(substr(replace(id::text, '-', ''), 1, 28)),\n        email = NULL, telefono = v_telefono, barrio = 'Anonimizado', direccion = NULL,\n        complemento = NULL, latitud = NULL,\n        longitud = NULL, geo_precision = NULL, notas = NULL, estado = 'cancelada',\n        dada_de_baja_en = coalesce(dada_de_baja_en, now()),\n        motivo_baja = 'Anonimizada (habeas data)', anonimizada_en = now()\n    WHERE id = p_familia;\n\n    -- El rastro en la bitacora, incluido el que acaba de dejar esta misma funcion.\n    v_ids := ARRAY(\n        SELECT p_familia::text\n        UNION SELECT f.usuario_portal_id::text WHERE f.usuario_portal_id IS NOT NULL\n        UNION SELECT id::text FROM mascotas WHERE familia_id = p_familia\n        UNION SELECT id::text FROM contactos_familia WHERE familia_id = p_familia\n        UNION SELECT id::text FROM documentos_familia WHERE familia_id = p_familia\n        UNION SELECT id::text FROM peludos_solicitud WHERE familia_id = p_familia\n        UNION SELECT id::text FROM interesados WHERE familia_id = p_familia\n        UNION SELECT id::text FROM mensajes WHERE familia_id = p_familia\n        UNION SELECT id::text FROM solicitudes_afiliacion WHERE familia_id = p_familia\n        UNION SELECT id::text FROM medios_pago_recurrente WHERE familia_id = p_familia\n        UNION SELECT id::text FROM encuestas WHERE familia_id = p_familia\n        UNION SELECT id::text FROM contratos WHERE familia_id = p_familia\n    );\n    UPDATE auditoria a\n    SET cambios = (\n        SELECT jsonb_object_agg(\n            e.k, CASE WHEN e.k = ANY (v_personales) THEN jsonb_build_array(v_anonimo, v_anonimo)\n                      ELSE e.v END)\n        FROM jsonb_each(a.cambios) AS e(k, v)\n    )\n    WHERE a.entidad_id = ANY (v_ids)\n      AND EXISTS (SELECT 1 FROM jsonb_object_keys(a.cambios) AS k WHERE k = ANY (v_personales));\n    RETURN;\nEND\n$$\n"

_ANONIMIZAR = "\nCREATE OR REPLACE FUNCTION anonimizar_familia(p_familia uuid) RETURNS SETOF text\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$\nDECLARE\n    f familias%ROWTYPE;\n    v_ids text[];\n    v_solicitudes uuid[];\n    v_servicios uuid[];\n    v_historias uuid[];\n    v_referencias text[];\n    v_tareas uuid[];\n    v_mensajes uuid[];\n    v_destinos text[];\n    v_coordenadas text[];\n    v_palabras text[];\n    v_literales text[];\n    v_anonimo constant text := '[anonimizado]';\n    -- Prefijo internacional 999: no esta asignado a ningun pais.\n    v_telefono constant text := '+99900000000';\n    v_quitar constant text[] :=\n        ARRAY['ip', 'agente', 'user_agent', 'nombre', 'documento', 'email', 'telefono'];\n    v_personales constant text[] := ARRAY[\n        'titular_nombre', 'documento', 'email', 'telefono', 'barrio', 'direccion', 'relacion',\n        'descripcion',\n        'complemento', 'latitud', 'longitud',\n        'notas', 'motivo_baja', 'nombre', 'destino', 'contenido', 'asunto', 'variables',\n        'email_titular', 'ultimos4', 'comentario', 'aceptacion', 'evidencia_aceptacion', 'datos',\n        'contacto_nombre', 'contacto_telefono', 'contacto_email', 'payload'\n    ];\n    -- Tablas cuya bitacora se limpia: filtrar por entidad deja usar ix_auditoria_entidad.\n    v_entidades constant text[] := ARRAY[\n        'familias', 'usuarios', 'mascotas', 'contactos_familia', 'documentos_familia',\n        'peludos_solicitud', 'interesados', 'mensajes', 'solicitudes_afiliacion',\n        'medios_pago_recurrente', 'encuestas', 'contratos', 'pagos', 'tareas', 'servicios',\n        'historias_clinicas', 'pendientes', 'solicitudes_virtuales', 'remisiones_aliadas',\n        'paradas_ruta', 'formulas', 'adjuntos_clinicos', 'eventos_preventivos', 'servicio_pasos'\n    ];\nBEGIN\n    IF current_setting('app.rol', true) IS DISTINCT FROM 'admin' THEN\n        RAISE EXCEPTION 'Solo un administrador anonimiza una familia'\n            USING ERRCODE = 'insufficient_privilege';\n    END IF;\n    SELECT * INTO f FROM familias WHERE id = p_familia FOR UPDATE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Familia % no encontrada', p_familia USING ERRCODE = 'no_data_found';\n    END IF;\n    IF f.anonimizada_en IS NOT NULL THEN\n        RAISE EXCEPTION 'La familia ya esta anonimizada' USING ERRCODE = 'check_violation';\n    END IF;\n    IF EXISTS (\n        SELECT 1 FROM contratos\n        WHERE familia_id = p_familia AND estado IN ('activa', 'en_mora', 'congelada')\n    ) THEN\n        RAISE EXCEPTION 'La familia tiene un contrato vigente' USING ERRCODE = 'check_violation';\n    END IF;\n\n    v_solicitudes := ARRAY(SELECT id FROM solicitudes_afiliacion WHERE familia_id = p_familia);\n    v_servicios := ARRAY(SELECT id FROM servicios WHERE familia_id = p_familia);\n    v_historias := ARRAY(SELECT id FROM historias_clinicas WHERE familia_id = p_familia);\n    v_referencias := ARRAY(SELECT referencia_externa FROM pagos WHERE familia_id = p_familia);\n    -- Lo que la identifica dentro de un texto libre (notas del equipo, historias, tareas):\n    -- nombres y direccion como palabras completas; documento, correos y telefonos (sin el\n    -- +57) donde aparezcan. Se calcula antes de borrarlos.\n    v_palabras := ARRAY(\n        SELECT DISTINCT x FROM unnest(\n            ARRAY[f.titular_nombre, f.direccion, f.complemento]\n            || ARRAY(SELECT nombre FROM contactos_familia WHERE familia_id = p_familia)\n            || ARRAY(\n                SELECT contacto_nombre FROM solicitudes_afiliacion\n                WHERE id = ANY (v_solicitudes)\n            )\n        ) AS x\n        WHERE length(x) >= 4\n    );\n    v_literales := ARRAY(\n        SELECT DISTINCT x FROM unnest(\n            ARRAY[f.documento, f.email, regexp_replace(f.telefono, '^\\+57', '')]\n            || ARRAY(SELECT email FROM contactos_familia WHERE familia_id = p_familia)\n            || ARRAY(\n                SELECT regexp_replace(telefono, '^\\+57', '') FROM contactos_familia\n                WHERE familia_id = p_familia\n            )\n            || ARRAY(\n                SELECT contacto_email FROM solicitudes_afiliacion WHERE id = ANY (v_solicitudes)\n            )\n            || ARRAY(\n                SELECT regexp_replace(contacto_telefono, '^\\+57', '')\n                FROM solicitudes_afiliacion WHERE id = ANY (v_solicitudes)\n            )\n        ) AS x\n        WHERE length(x) >= 6\n    );\n    -- Los mensajes del registro en linea salieron antes de que existiera la familia.\n    v_destinos := ARRAY(\n        SELECT DISTINCT x FROM unnest(\n            ARRAY[f.email, f.telefono]\n            || ARRAY(\n                SELECT contacto_email FROM solicitudes_afiliacion WHERE id = ANY (v_solicitudes)\n            )\n            || ARRAY(\n                SELECT contacto_telefono FROM solicitudes_afiliacion\n                WHERE id = ANY (v_solicitudes)\n            )\n        ) AS x\n        WHERE x IS NOT NULL\n    );\n    v_mensajes := ARRAY(\n        SELECT id FROM mensajes\n        WHERE familia_id = p_familia OR (familia_id IS NULL AND destino = ANY (v_destinos))\n    );\n    -- Sus tareas, tambien las del registro en linea, que nacen sin familia.\n    v_tareas := ARRAY(\n        SELECT id FROM tareas\n        WHERE familia_id = p_familia\n           OR clave = ANY (\n               ARRAY(\n                   SELECT k || ':' || s::text\n                   FROM unnest(v_solicitudes) AS s,\n                        unnest(ARRAY[\n                            'registro_sin_formulario', 'registro_sin_pago', 'registro_revision',\n                            'afiliacion_pago_reemplazada'\n                        ]) AS k\n               )\n               || ARRAY(SELECT 'registro_pago_doble:' || r FROM unnest(v_referencias) AS r)\n           )\n    );\n    -- La casa en la cache de distancias: la clave es la coordenada con 4 decimales\n    -- (rutas/distancias.py), la de la ficha y la que copiaron sus paradas de ruta.\n    v_coordenadas := ARRAY(\n        SELECT DISTINCT round(c.lat::numeric, 4)::text || ',' || round(c.lon::numeric, 4)::text\n        FROM (\n            SELECT f.latitud AS lat, f.longitud AS lon\n            UNION SELECT latitud, longitud FROM paradas_ruta WHERE servicio_id = ANY (v_servicios)\n        ) AS c\n        WHERE c.lat IS NOT NULL AND c.lon IS NOT NULL\n    );\n\n    -- Ficheros con datos personales: fotos de las mascotas, PDF de contratos, carnets y\n    -- formulas (llevan el nombre del titular y se regeneran con sus datos) y los documentos\n    -- que subio el equipo, salvo los examenes externos, que son clinicos.\n    RETURN QUERY\n        WITH purgados AS (\n            UPDATE archivos a SET purgado_en = now(), nombre_original = 'anonimizado'\n            WHERE a.purgado_en IS NULL AND a.id IN (\n                SELECT foto_archivo_id FROM mascotas WHERE familia_id = p_familia\n                UNION SELECT documento_archivo_id FROM contratos WHERE familia_id = p_familia\n                UNION SELECT c.archivo_id FROM carnets_emitidos c\n                      JOIN mascotas m ON m.id = c.mascota_id WHERE m.familia_id = p_familia\n                UNION SELECT archivo_id FROM formulas WHERE historia_id = ANY (v_historias)\n                UNION SELECT archivo_id FROM documentos_familia\n                      WHERE familia_id = p_familia AND categoria <> 'examen_externo'\n            )\n            RETURNING a.clave\n        )\n        SELECT clave::text FROM purgados;\n\n    -- Lo clinico se conserva, sin las menciones a la familia en su texto libre.\n    UPDATE historias_clinicas\n    SET motivo = borrar_menciones(motivo, v_palabras, v_literales),\n        anamnesis = borrar_menciones(anamnesis, v_palabras, v_literales),\n        examen_fisico = borrar_menciones(examen_fisico, v_palabras, v_literales),\n        diagnostico = borrar_menciones(diagnostico, v_palabras, v_literales),\n        tratamiento = borrar_menciones(tratamiento, v_palabras, v_literales),\n        notas_internas = borrar_menciones(notas_internas, v_palabras, v_literales)\n    WHERE id = ANY (v_historias);\n    UPDATE formulas SET indicaciones = borrar_menciones(indicaciones, v_palabras, v_literales)\n    WHERE historia_id = ANY (v_historias);\n    UPDATE adjuntos_clinicos\n    SET descripcion = borrar_menciones(descripcion, v_palabras, v_literales),\n        nombre_archivo = borrar_menciones(nombre_archivo, v_palabras, v_literales)\n    WHERE historia_id = ANY (v_historias);\n    UPDATE servicios\n    SET observaciones = borrar_menciones(observaciones, v_palabras, v_literales),\n        motivo_estado = borrar_menciones(motivo_estado, v_palabras, v_literales)\n    WHERE id = ANY (v_servicios);\n    UPDATE servicio_pasos SET datos = borrar_menciones_json(datos, v_palabras, v_literales)\n    WHERE servicio_id = ANY (v_servicios);\n    UPDATE pendientes\n    SET descripcion = borrar_menciones(descripcion, v_palabras, v_literales),\n        resolucion = borrar_menciones(resolucion, v_palabras, v_literales)\n    WHERE servicio_origen_id = ANY (v_servicios);\n    UPDATE solicitudes_virtuales\n    SET motivo = borrar_menciones(motivo, v_palabras, v_literales),\n        respuesta = borrar_menciones(respuesta, v_palabras, v_literales),\n        borrador_ia = borrar_menciones_json(borrador_ia, v_palabras, v_literales)\n    WHERE familia_id = p_familia;\n    UPDATE remisiones_aliadas\n    SET motivo = borrar_menciones(motivo, v_palabras, v_literales),\n        resumen_atencion = borrar_menciones(resumen_atencion, v_palabras, v_literales)\n    WHERE familia_id = p_familia;\n    UPDATE eventos_preventivos\n    SET motivo_cancelacion = borrar_menciones(motivo_cancelacion, v_palabras, v_literales)\n    WHERE mascota_id IN (SELECT id FROM mascotas WHERE familia_id = p_familia);\n    UPDATE consultas_ia\n    SET entrada = borrar_menciones(entrada, v_palabras, v_literales),\n        salida = borrar_menciones(salida, v_palabras, v_literales)\n    WHERE contexto = ANY (\n        ARRAY(SELECT 'solicitud:' || id FROM solicitudes_virtuales WHERE familia_id = p_familia)\n    );\n    -- La IA comercial guarda el mensaje de la persona con su telefono: es suyo entero.\n    UPDATE consultas_ia SET entrada = v_anonimo, salida = v_anonimo, contexto = 'whatsapp:'\n    WHERE contexto IN ('whatsapp:' || f.telefono, 'whatsapp:' || ltrim(f.telefono, '+'));\n    UPDATE paradas_ruta\n    SET latitud = NULL, longitud = NULL,\n        nota = borrar_menciones(nota, v_palabras, v_literales),\n        motivo_omision = borrar_menciones(motivo_omision, v_palabras, v_literales)\n    WHERE servicio_id = ANY (v_servicios);\n    DELETE FROM distancias_cache\n    WHERE origen = ANY (v_coordenadas) OR destino = ANY (v_coordenadas);\n    UPDATE tareas\n    SET titulo = borrar_menciones(titulo, v_palabras, v_literales),\n        descripcion = borrar_menciones(descripcion, v_palabras, v_literales),\n        resolucion = borrar_menciones(resolucion, v_palabras, v_literales)\n    WHERE id = ANY (v_tareas);\n    -- Lo que la pasarela guardo del pagador; lo contable (valor, fecha, referencia) queda.\n    UPDATE pagos SET payload = NULL, notas = borrar_menciones(notas, v_palabras, v_literales)\n    WHERE familia_id = p_familia;\n    UPDATE eventos_pasarela\n    SET payload = payload\n        #- '{data,transaction,customer_email}' #- '{data,transaction,customer_data}'\n        #- '{data,transaction,shipping_address}' #- '{data,transaction,billing_data}'\n    WHERE referencia = ANY (v_referencias);\n\n    UPDATE mascotas SET nombre = 'Mascota', foto_archivo_id = NULL WHERE familia_id = p_familia;\n    UPDATE peludos_solicitud SET nombre = 'Mascota' WHERE familia_id = p_familia;\n    IF f.usuario_portal_id IS NOT NULL THEN\n        UPDATE usuarios\n        SET nombre = 'Anonimizado', email = 'anonimizado-' || id || '@invalid.local',\n            telefono = NULL, activo = false\n        WHERE id = f.usuario_portal_id;\n        UPDATE sesiones\n        SET revocada_en = coalesce(revocada_en, now()), ip = NULL, user_agent = NULL\n        WHERE usuario_id = f.usuario_portal_id;\n        UPDATE tokens_uso_unico SET expira_en = least(expira_en, now())\n        WHERE usuario_id = f.usuario_portal_id;\n    END IF;\n    DELETE FROM conversaciones_comerciales\n    WHERE telefono = f.telefono\n       OR interesado_id IN (SELECT id FROM interesados WHERE familia_id = p_familia);\n    DELETE FROM conversaciones_whatsapp WHERE familia_id = p_familia OR telefono = f.telefono;\n    UPDATE interesados SET nombre = NULL, telefono = NULL, email = NULL, datos = '{}'\n    WHERE familia_id = p_familia;\n    UPDATE mensajes SET destino = NULL, contenido = NULL, asunto = NULL, variables = '[]'\n    WHERE id = ANY (v_mensajes);\n    UPDATE solicitudes_afiliacion SET aceptacion = aceptacion - v_quitar,\n        contacto_nombre = CASE WHEN contacto_nombre IS NULL THEN NULL ELSE 'Anonimizado' END,\n        contacto_telefono = CASE WHEN contacto_telefono IS NULL THEN NULL ELSE v_telefono END,\n        contacto_email = NULL\n    WHERE familia_id = p_familia;\n    UPDATE contratos SET evidencia_aceptacion = evidencia_aceptacion - v_quitar\n    WHERE familia_id = p_familia;\n    UPDATE medios_pago_recurrente\n    SET email_titular = 'anonimizado@invalid.local', ultimos4 = NULL, activo = false\n    WHERE familia_id = p_familia;\n    UPDATE encuestas SET comentario = NULL WHERE familia_id = p_familia;\n    UPDATE destinatarios_campana SET telefono = v_telefono WHERE familia_id = p_familia;\n    UPDATE documentos_familia SET descripcion = NULL WHERE familia_id = p_familia;\n    -- Tambien los que se conservan: el nombre original puede llevar datos personales.\n    UPDATE archivos SET nombre_original = 'anonimizado'\n    WHERE id IN (\n        SELECT archivo_id FROM documentos_familia WHERE familia_id = p_familia\n        UNION SELECT archivo_id FROM adjuntos_clinicos WHERE historia_id = ANY (v_historias)\n    );\n    UPDATE contactos_familia\n    SET nombre = 'Anonimizado', telefono = v_telefono, email = NULL, relacion = NULL\n    WHERE familia_id = p_familia;\n    UPDATE familias\n    SET titular_nombre = 'Anonimizado',\n        documento = 'ANON' || upper(substr(replace(id::text, '-', ''), 1, 28)),\n        email = NULL, telefono = v_telefono, barrio = 'Anonimizado', direccion = NULL,\n        complemento = NULL, latitud = NULL,\n        longitud = NULL, geo_precision = NULL, notas = NULL, estado = 'cancelada',\n        dada_de_baja_en = coalesce(dada_de_baja_en, now()),\n        motivo_baja = 'Anonimizada (habeas data)', anonimizada_en = now()\n    WHERE id = p_familia;\n\n    -- El rastro en la bitacora, incluido el que acaba de dejar esta misma funcion.\n    v_ids := ARRAY(\n        SELECT p_familia::text\n        UNION SELECT f.usuario_portal_id::text WHERE f.usuario_portal_id IS NOT NULL\n        UNION SELECT id::text FROM mascotas WHERE familia_id = p_familia\n        UNION SELECT id::text FROM contactos_familia WHERE familia_id = p_familia\n        UNION SELECT id::text FROM documentos_familia WHERE familia_id = p_familia\n        UNION SELECT id::text FROM peludos_solicitud WHERE familia_id = p_familia\n        UNION SELECT id::text FROM interesados WHERE familia_id = p_familia\n        UNION SELECT m::text FROM unnest(v_mensajes) AS m\n        UNION SELECT s::text FROM unnest(v_solicitudes) AS s\n        UNION SELECT id::text FROM medios_pago_recurrente WHERE familia_id = p_familia\n        UNION SELECT id::text FROM encuestas WHERE familia_id = p_familia\n        UNION SELECT id::text FROM contratos WHERE familia_id = p_familia\n        UNION SELECT id::text FROM pagos WHERE familia_id = p_familia\n        UNION SELECT t::text FROM unnest(v_tareas) AS t\n        UNION SELECT s::text FROM unnest(v_servicios) AS s\n        UNION SELECT h::text FROM unnest(v_historias) AS h\n        UNION SELECT id::text FROM pendientes WHERE servicio_origen_id = ANY (v_servicios)\n        UNION SELECT id::text FROM solicitudes_virtuales WHERE familia_id = p_familia\n        UNION SELECT id::text FROM remisiones_aliadas WHERE familia_id = p_familia\n        UNION SELECT id::text FROM paradas_ruta WHERE servicio_id = ANY (v_servicios)\n        UNION SELECT id::text FROM servicio_pasos WHERE servicio_id = ANY (v_servicios)\n        UNION SELECT id::text FROM formulas WHERE historia_id = ANY (v_historias)\n        UNION SELECT id::text FROM adjuntos_clinicos WHERE historia_id = ANY (v_historias)\n        UNION SELECT e.id::text FROM eventos_preventivos e\n              JOIN mascotas m ON m.id = e.mascota_id WHERE m.familia_id = p_familia\n    );\n    -- Los campos personales enteros; en los demas (lo clinico), solo las menciones.\n    UPDATE auditoria a\n    SET cambios = (\n        SELECT jsonb_object_agg(\n            e.k, CASE WHEN e.k = ANY (v_personales) THEN jsonb_build_array(v_anonimo, v_anonimo)\n                      ELSE borrar_menciones_json(e.v, v_palabras, v_literales) END)\n        FROM jsonb_each(a.cambios) AS e(k, v)\n    )\n    WHERE a.entidad = ANY (v_entidades) AND a.entidad_id = ANY (v_ids)\n      AND a.cambios <> '{}'::jsonb;\n    RETURN;\nEND\n$$\n"

_FUNCIONES = (
    "borrar_menciones(text, text[], text[])",
    "borrar_menciones_json(jsonb, text[], text[])",
)


def upgrade() -> None:
    op.execute(_BORRAR_MENCIONES)
    op.execute(_BORRAR_MENCIONES_JSON)
    # Solo las usa anonimizar_familia(), que corre como dueno del esquema.
    for funcion in _FUNCIONES:
        op.execute(f"REVOKE ALL ON FUNCTION {funcion} FROM PUBLIC")
    op.execute(_ANONIMIZAR)


def downgrade() -> None:
    op.execute(_ANONIMIZAR_ANTERIOR)
    for funcion in reversed(_FUNCIONES):
        op.execute(f"DROP FUNCTION {funcion}")
